               style={{ backgroundColor: colors.brandTertiary, color: colors.onBrandTertiary }}>
            <CalendarClock size={20} />
          </div>
          <div>
            <h1 className="text-2xl md:text-3xl font-bold" style={{ color: colors.onSurface }}>Recurring Jobs</h1>
            <p className="text-sm mt-0.5" style={{ color: colors.muted }}>
              Auto-generates a rolling 2-week horizon of jobs. Nightly cron @ 02:00 UTC.
            </p>
          </div>
        </div>
        <button type="button" onClick={openCreate}
                className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md"
                style={{ background: colors.brand, color: "#fff", border: 0 }}
                data-testid="recurring-jobs-create">
          <Plus size={14} /> New recurring job
        </button>
        {/* Feb-2026 · P1 Auto-Activate + Bulk Activate — green
             toolbar button that flips ``is_active=True`` on every
             selected template AND fires the 14-day inline generator
             so operators see near-term visits without waiting for
             the nightly cron. Sits immediately BEFORE the
             destructive "Delete permanently" button; both share the
             same disabled-when-empty visual language. */}
        <button
          type="button"
          onClick={bulkActivate}
          disabled={selectedIds.size === 0 || bulkActivateBusy}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#DCFCE7" : "#059669",
            color: selectedIds.size === 0 ? "#065F46" : "#FFFFFF",
            border: 0,
            opacity: (selectedIds.size === 0 || bulkActivateBusy) ? 0.5 : 1,
            cursor: (selectedIds.size === 0 || bulkActivateBusy)
              ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0 || bulkActivateBusy}
          data-testid="recurring-bulk-activate"
        >
          <Play size={14} />{" "}
          {bulkActivateBusy ? "Activating…" :
            `Bulk Activate${selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}`}
        </button>
        {/* Phase P54 · Feb-2026 — Bulk Edit Categories toolbar
             button. Sits between the green "Bulk Activate" and
             the destructive red "Delete permanently" — neutral
             indigo affordance so it visually reads as an
             *editing* action, not activating or destroying.
             Always rendered so testid is queryable; disabled +
             semi-opaque when no rows are checked. */}
        <button
          type="button"
          onClick={() => {
            setBulkEditServiceCat("");
            setBulkEditIncomeCat("");
            setBulkEditError("");
            setBulkEditOpen(true);
          }}
          disabled={selectedIds.size === 0 || bulkEditBusy}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#E0E7FF" : "#4F46E5",
            color: selectedIds.size === 0 ? "#3730A3" : "#FFFFFF",
            border: 0,
            opacity: (selectedIds.size === 0 || bulkEditBusy) ? 0.5 : 1,
            cursor: (selectedIds.size === 0 || bulkEditBusy)
              ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0 || bulkEditBusy}
          data-testid="recurring-bulk-edit-categories"
        >
          <Tag size={14} />{" "}
          {bulkEditBusy ? "Applying…" :
            `Bulk Edit Categories${selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}`}
        </button>
        {/* Phase R1 · Feb-2026 — bulk hard-delete toolbar button.
             Always rendered so its testid is queryable by unit
             tests + Playwright; disabled when nothing is
             selected. The label appends the running count so
             ops always sees ``Delete permanently (N)`` — the
             count comes from the visible-page checkbox state,
             not the server. */}
        <button
          type="button"
          onClick={() => { setBulkAcked(false); setBulkModalOpen(true); }}
          disabled={selectedIds.size === 0}
          className="inline-flex items-center gap-1 text-sm font-bold px-3 py-2 rounded-md ml-2"
          style={{
            background: selectedIds.size === 0 ? "#FEE2E2" : "#B91C1C",
            color: selectedIds.size === 0 ? "#B91C1C" : "#FFFFFF",
            border: 0,
            opacity: selectedIds.size === 0 ? 0.5 : 1,
            cursor: selectedIds.size === 0 ? "not-allowed" : "pointer",
          }}
          aria-disabled={selectedIds.size === 0}
          data-testid="recurring-bulk-hard-delete"
        >
          <Trash2 size={14} />{" "}
          Delete permanently{selectedIds.size > 0 ? ` (${selectedIds.size})` : ""}
        </button>
      </div>

      {error ? (
        <div className="rounded-2xl p-3 mb-4 text-sm"
             style={{ background: "#FEF2F2", border: "1px solid #FECACA", color: "#B91C1C" }}
             data-testid="recurring-jobs-error">{error}</div>
      ) : null}

      {/* Feb-2026 P0 · Orphan cluster banner. Renders only when the
          orphan-preview scan found at least one cluster missing a
          matching template. Operator can click "Backfill now" to
          mint them; idempotent so re-running is safe.

          Phase P14 · Feb-2026 · Item 2 — same yellow banner
          container now ALSO carries a red "Delete all orphans
          permanently" button when the purge-preview scan found
          templates whose ``customer_id`` doesn't resolve. Banner
          renders when EITHER preview is non-zero so the operator
          sees whichever remediation applies. */}
      {(orphanPreview && orphanPreview.orphan_count > 0)
       || (purgePreview && purgePreview.count > 0) ? (
        <div
          className="rounded-2xl p-4 mb-4 text-sm flex items-start justify-between gap-3"
          style={{ background: "#FEF3C7", border: "1px solid #FCD34D",
                    color: "#78350F" }}
          data-testid="recurring-jobs-orphan-banner"
        >
          <div>
            {orphanPreview && orphanPreview.orphan_count > 0 ? (
              <>
                <div className="font-bold">
                  {orphanPreview.orphan_count} recurring customer
                  {orphanPreview.orphan_count === 1 ? "" : "s"} missing from this list.
                </div>
                <div className="mt-0.5 text-xs">
                  Detected {orphanPreview.total_occurrences} pre-scheduled visits from
                  the Schedule page that have no matching recurring template. Click
                  &ldquo;Backfill now&rdquo; to add them here — existing entries won&rsquo;t be touched.
                </div>
              </>
            ) : null}
            {purgePreview && purgePreview.count > 0 ? (
              <div
                className={orphanPreview && orphanPreview.orphan_count > 0 ? "mt-2" : ""}
                data-testid="recurring-jobs-purge-summary"
              >
                <div className="font-bold">
                  {purgePreview.count} orphaned recurring
                  job{purgePreview.count === 1 ? "" : "s"} with a deleted customer.
                </div>
                <div className="mt-0.5 text-xs">
                  These templates point at a ``customer_id`` that no longer
                  resolves in this tenant — safe to delete permanently.
                </div>
              </div>
            ) : null}
          </div>
          <div className="flex flex-col gap-2 shrink-0">
            {orphanPreview && orphanPreview.orphan_count > 0 ? (
              <button
                type="button"
                onClick={runBackfill}
                disabled={orphanBusy}
                className="inline-flex items-center gap-1 text-xs font-bold px-3 py-2 rounded-md whitespace-nowrap"
                style={{ background: "#B45309", color: "#FFFFFF", border: 0,
                          opacity: orphanBusy ? 0.5 : 1 }}
                data-testid="recurring-jobs-backfill-btn"
              >
                {orphanBusy ? "Backfilling…" : "Backfill now"}
              </button>
            ) : null}
            {purgePreview && purgePreview.count > 0 ? (
              <button
                type="button"
                onClick={() => { setPurgeInput(""); setPurgeConfirmOpen(true); }}
                disabled={purgeBusy}
                className="inline-flex items-center gap-1 text-xs font-bold px-3 py-2 rounded-md whitespace-nowrap"
                style={{ background: "#B91C1C", color: "#FFFFFF", border: 0,
                          opacity: purgeBusy ? 0.5 : 1 }}
                data-testid="recurring-jobs-purge-btn"
              >
                {purgeBusy
                  ? "Deleting…"
                  : `Delete all orphans permanently (${purgePreview.count})`}
              </button>
            ) : null}
          </div>
        </div>
      ) : null}

      {/* Phase P14 · Feb-2026 · Item 2 — purge confirm dialog.
          Requires the operator to type ``DELETE`` verbatim. Same
          shadcn ``Dialog`` primitive the rest of the page's
          destructive flows use, kept intentionally minimal so it
          fits inside the existing dialog stack without z-index
          fights. */}
      {purgeConfirmOpen ? (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center"
          style={{ background: "rgba(15,23,42,0.55)" }}
          data-testid="recurring-jobs-purge-confirm"
        >
          <div
            className="w-full max-w-md rounded-2xl p-5 space-y-3"
            style={{ background: colors.surface, border: `1px solid ${colors.border}` }}
          >
            <h2 className="text-lg font-bold" style={{ color: colors.onSurface }}>
              Delete orphaned recurring jobs?
            </h2>
            <p className="text-sm" style={{ color: colors.muted }}>
              This will permanently delete{" "}
              <b>{purgePreview?.count || 0}</b>{" "}
              orphaned recurring job{(purgePreview?.count || 0) === 1 ? "" : "s"}.
              This cannot be undone.
            </p>
            <label className="text-xs font-semibold block" style={{ color: colors.muted }}>
              Type DELETE to confirm
              <input
                type="text"
                value={purgeInput}
                onChange={(e) => setPurgeInput(e.target.value)}
                className="w-full mt-1 px-2 py-1.5 rounded text-sm"
                style={{
                  border: `1px solid ${colors.border}`,
                  background: colors.surface,
                  color: colors.onSurface,
                }}
                data-testid="recurring-jobs-purge-input"
                autoFocus
              />
            </label>
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => { setPurgeConfirmOpen(false); setPurgeInput(""); }}
                disabled={purgeBusy}
                className="px-3 py-1.5 rounded-md text-sm"
                style={{ border: `1px solid ${colors.border}`, background: colors.surface, color: colors.onSurface }}
                data-testid="recurring-jobs-purge-cancel"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={runPurgeOrphans}
                disabled={purgeBusy || (purgeInput || "").trim() !== "DELETE"}
                className="px-3 py-1.5 rounded-md text-sm font-bold"
                style={{
                  background: "#B91C1C", color: "#FFFFFF", border: 0,
                  opacity: (purgeBusy || (purgeInput || "").trim() !== "DELETE") ? 0.5 : 1,
                }}
                data-testid="recurring-jobs-purge-commit"
              >
                {purgeBusy ? "Deleting…" : "Delete permanently"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      {loading ? (
        <div className="rounded-2xl p-8 text-center text-sm"
             style={{ background: colors.surface, border: `1px solid ${colors.border}`, color: colors.muted }}>
          Loading…
        </div>
      ) : (
        <>
        {/* Phase P18 · Feb-2026 — Active / Paused tab switcher.
             Counts come from the tenant-wide aggregate returned by
             the backend so the badge stays honest even when the
             client-side customer search filter narrows the visible
             row set. URL query ``?status=`` is the source of truth
             for the selected tab. */}
        <div
          className="flex items-center gap-1 mb-4 rounded-xl p-1 w-fit"
          style={{ background: colors.surfaceSecondary,
                    border: `1px solid ${colors.border}` }}
          role="tablist"
          aria-label="Recurring jobs status filter"
          data-testid="recurring-status-tabs"
        >
          {[
            { key: "active", label: "Active" },
            { key: "paused", label: "Paused" },
          ].map((tab) => {
            const isActive = statusTab === tab.key;
            const badge = Number(tabCounts[tab.key] || 0);
            return (
              <button
                key={tab.key}
                type="button"
                role="tab"
                aria-selected={isActive}
                onClick={() => setStatusTab(tab.key)}
                disabled={loading || busy != null}
                className="px-3 py-1.5 text-sm font-semibold rounded-lg transition-colors disabled:opacity-60"
                style={{
                  backgroundColor: isActive ? "#FFFFFF" : "transparent",
                  color: isActive ? colors.onSurface : colors.muted,
                  border: isActive
                    ? `1px solid ${colors.border}`
                    : "1px solid transparent",
                }}
                data-testid={`recurring-status-tab-${tab.key}`}
                data-count={badge}
              >
                {tab.label} ({badge})
              </button>
            );
          })}
        </div>
        {/* Phase R2 · Feb-2026 — customer search.  Client-side
             filter; bulk-select "on page" scopes to filtered rows.
             Phase P54 · Feb-2026 — service-category filter dropdown
             now sits alongside the search input.  Both filters
             AND together (search AND category) and drive the same
             ``filteredItems`` memo so bulk-select "on page" scopes
             to the intersection.

             Task E · Feb-2026 — Bare filter row → NavyFilterBar
             navy chrome. Search input paints solid-white +
             permanent ``#3B82F6`` border + navy text (decision
             #1); service-category select goes navy w/ white text.
             The Clear-X inside the search reuses the legacy
             ``recurring-search-clear`` testid via NavyFilterBar
             .Search's ``clearTestid`` override so the P54 vitest
             wiring stays intact. */}
        <NavyFilterBar
          data-testid="recurring-jobs-filters"
          data-k52-navy-strip="true"
        >
          <NavyFilterBar.Search
            value={searchInput}
            onChange={setSearchInput}
            placeholder={t("search_customer_placeholder", "Search by customer name…")}
            ariaLabel="Search recurring jobs by customer"
            data-testid="recurring-search-input"
            onClear={() => setSearchInput("")}
            clearTestid="recurring-search-clear"
            className="max-w-md"
          />
          <NavyFilterBar.Select
            value={serviceCategoryFilter}
            onChange={setServiceCategoryFilter}
            ariaLabel="Filter recurring jobs by service category"
            data-testid="recurring-jobs-service-category-filter"
            minWidth={180}
          >
            <option value="">All categories</option>
            {serviceCats.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </NavyFilterBar.Select>
        </NavyFilterBar>
        <div className="rounded-2xl overflow-x-auto"
             style={{ background: colors.surface, border: `1px solid ${colors.border}` }}>
          <table className="w-full text-sm" data-testid="recurring-jobs-table">
            <thead>
              <tr style={{ borderBottom: `1px solid ${colors.border}` }}>
                {/* Phase R1 · Feb-2026 — bulk-select header cell.
                     Tri-state semantics: unchecked when nothing on
                     the page is selected, checked when EVERY visible
                     row is selected, ``indeterminate`` when some
                     rows are selected. */}
                <th className="px-3 py-2.5" style={{ width: "36px" }}>
                  <input
                    type="checkbox"
                    checked={_allVisibleSelected()}
                    ref={(el) => {
                      if (el) {
                        el.indeterminate = !_allVisibleSelected() && _someVisibleSelected();
                      }
                    }}
                    onChange={_toggleAllVisible}
                    aria-label="Select all recurring jobs on this page"
                    data-testid="recurring-select-all"
                    className="cursor-pointer"
                  />
                </th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Customer</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Service</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold"
                     style={{ color: colors.muted }}
                     data-testid="recurring-th-service-category">
                  Service Category
                </th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold"
                     style={{ color: colors.muted }}
                     data-testid="recurring-th-income-category">
                  Income Category
                </th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Frequency</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Next</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold"
                     style={{ color: colors.muted }}
                     data-testid="recurring-th-end-date">
                  End Date
                </th>
                <th className="text-right px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Price</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold" style={{ color: colors.muted }}>Status</th>
                <th className="text-left px-3 py-2.5 uppercase text-[11px] font-semibold"
                     style={{ color: colors.muted }}
                     data-testid="recurring-th-actions">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody>
              {filteredItems.length === 0 ? (
                <tr><td colSpan={11} className="px-4 py-8 text-center text-sm"
                       style={{ color: colors.muted }} data-testid="recurring-jobs-empty">
                  {items.length === 0
                    ? "No recurring jobs yet — click \"New recurring job\" to add your first."
                    : "No recurring jobs match your search."}
                </td></tr>
              ) : filteredItems.map((r) => (
                <tr key={r.id} data-testid={`recurring-job-row-${r.id}`}
                    tabIndex={0}
                    onClick={() => openEdit(r)}
                    onKeyDown={(e) => {
                      // Phase P3 · Feb-2026 — Enter (and Space, per
                      // WAI-ARIA button pattern) on a focused row
                      // opens the Edit modal. Anywhere-else key
                      // events bubble normally (e.g. Tab, arrow
                      // keys) so the row stays keyboard-navigable.
                      if (e.key === "Enter" || e.key === " ") {
                        // Only act when the event target is the
                        // <tr> itself — not a nested input /
                        // button / checkbox — so typing space in a
                        // future editable cell doesn't accidentally
                        // fire.
                        if (e.currentTarget === e.target) {
                          e.preventDefault();
                          openEdit(r);
                        }
                      }
                    }}
                    style={{ borderBottom: `1px solid ${colors.border}`,
                              backgroundColor: selectedIds.has(r.id)
                                ? "#EFF6FF" : "transparent",
                              cursor: "pointer" }}
                    onMouseEnter={(e) => {
                      // Hover state — reuses the Brand Blue tint
                      // token already declared in theme.js. Skip
                      // if the row is already in the selected
                      // (blue-tinted) state so the two visual
                      // signals don't fight each other.
                      if (!selectedIds.has(r.id)) {
                        e.currentTarget.style.backgroundColor = colors.brandTertiary;
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (!selectedIds.has(r.id)) {
                        e.currentTarget.style.backgroundColor = "transparent";
                      }
                    }}>
                  {/* Phase R1 · Feb-2026 — bulk-select row checkbox.
                       Phase P3 · Feb-2026 — the wrapping <td> AND
                       the <input> both stop click / mousedown
                       propagation so ticking the box doesn't
                       ALSO fire the row-click handler above. */}
                  <td className="px-3 py-2.5" style={{ width: "36px" }}
                       onClick={(e) => e.stopPropagation()}
                       onMouseDown={(e) => e.stopPropagation()}>
                    <input
                      type="checkbox"
                      checked={selectedIds.has(r.id)}
                      onChange={() => _toggleOne(r.id)}
                      onClick={(e) => e.stopPropagation()}
                      onMouseDown={(e) => e.stopPropagation()}
                      aria-label={`Select ${r.customer_name || r.id}`}
                      data-testid={`recurring-row-checkbox-${r.id}`}
                      className="cursor-pointer"
                    />
                  </td>
                  <td className="px-3 py-2.5" style={{ color: colors.onSurface }}><CustomerLink customerId={r.customer_id} name={r.customer_name} /></td>
                  <td className="px-3 py-2.5 text-xs" style={{ color: colors.muted }}>{r.service_type}</td>
                  <td className="px-3 py-2.5"
                       data-testid={`recurring-cell-service-category-${r.id}`}>
                    <CategoryComboCell
                      axis="service"
                      row={r}
                      value={r.service_category_name || ""}
                      patchUrl={`/recurring-jobs/${r.id}`}
                      onPatched={(patch) => setItems((prev) =>
                        prev.map((x) => x.id === r.id ? { ...x, ...patch } : x))}
                    />
                  </td>
                  <td className="px-3 py-2.5"
                       data-testid={`recurring-cell-income-category-${r.id}`}>
                    <CategoryComboCell
                      axis="income"
                      row={r}
                      value={r.income_category_name || ""}
                      patchUrl={`/recurring-jobs/${r.id}`}
                      onPatched={(patch) => setItems((prev) =>
                        prev.map((x) => x.id === r.id ? { ...x, ...patch } : x))}
                    />
                  </td>
                  <td className="px-3 py-2.5 text-xs" style={{ color: colors.muted }}>
                    {r.frequency}{r.frequency === "weekly" || r.frequency === "biweekly" ? ` (${DOW[r.day_of_week] || "?"})` : ""}
                    {r.frequency === "monthly" ? ` (day ${r.day_of_month})` : ""}
                    {r.frequency === "custom" ? ` (${r.interval_days}d)` : ""}
                  </td>
                  <td className="px-3 py-2.5 text-xs" style={{ color: colors.muted }}>
                    {(r.upcoming || []).slice(0, 1).join(", ") || "—"}
                  </td>
                  <td className="px-3 py-2.5 text-xs"
                       style={{ color: colors.muted }}
                       data-testid={`recurring-cell-end-date-${r.id}`}>
                    {r.end_date || "—"}
                  </td>
                  <td className="px-3 py-2.5 text-right font-semibold" style={{ color: colors.onSurface }}>
                    {fmtMoney(r.price_cents)}
                  </td>
                  <td className="px-3 py-2.5">
                    <span className="inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase"
                          style={r.active
                            ? { background: "#DCFCE7", color: "#166534" }
                            : { background: "#FEE2E2", color: "#991B1B" }}>
                      {r.active ? "Active" : "Paused"}
                    </span>
                    {/* Feb-2026 · Recurring Jobs · is_active badge.
                        Rendered when the new gate is explicitly off,
                        distinct from the legacy "Paused" (which
                        derives from ``active``). A row can be
                        "Paused + Inactive" simultaneously — both
                        chips render side-by-side. */}
                    {r.is_active === false ? (
                      <span className="inline-block ml-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase"
                            style={{ background: "#FEF3C7", color: "#92400E" }}
                            data-testid={`recurring-job-inactive-badge-${r.id}`}>
                        Inactive
                      </span>
                    ) : null}
                    {/* Feb-2026 · Recommended Schedule auto-assign v1.
                        Persistent breadcrumb — this template was
                        placed by the route-proximity centroid pick,
                        not by a human choosing a tech/day. Tooltip
                        surfaces the extra-drive-time estimate. */}
                    {r.auto_assigned ? (
                      <span
                        className="inline-flex items-center gap-1 ml-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase"
                        style={{ background: "#DBEAFE", color: "#1E3A8A" }}
                        title={`via route proximity · +${r.auto_assign_extra_minutes || 0}m extra drive time`}
                        data-testid={`recurring-job-auto-assign-badge-${r.id}`}
                      >
                        <Sparkles size={9} /> Auto-assigned
                      </span>
                    ) : null}
                  </td>
                  <td className="px-3 py-2.5 text-right whitespace-nowrap">
                    {/* Phase P3 · Feb-2026 — 3-dot Actions menu.
                         Sits at the LEFT of the existing inline
                         button strip so the primary affordances
                         (Edit / Pause-Resume / Delete permanently)
                         are one click away without hunting through
                         the row. Existing inline buttons stay
                         behind it — they satisfy pre-P3 vitests
                         that assert those specific testids.  The
                         menu's own click handler stops the
                         propagation up to the <tr> row-click. */}
                    <RecurringRowActionsMenu
                      row={r}
                      canHardDelete={canHardDelete}
                      onEdit={() => openEdit(r)}
                      onTogglePause={() => togglePause(r)}
                      onHardDelete={() => setHardDeleteTarget(r)}
                    />
