                      ? ""
                      : "Enter a valid price");
                  }}
                  onBlur={() => {
                    // Normalize on blur only — don't re-format
                    // mid-edit or the caret jumps.
                    if (_validatePrice(priceStr)) {
                      const n = Number(priceStr.replace("$", ""));
                      setPriceStr(n.toFixed(2));
                    }
                  }}
                  aria-invalid={!!priceErr}
                  className="w-full mt-1 px-2 py-1.5 rounded text-sm"
                  style={{ border: `1px solid ${priceErr ? colors.error : colors.border}`, background: colors.surface, color: colors.onSurface }}
                  data-testid="recurring-jobs-price" />
                {priceErr ? (
                  <span className="block text-xs mt-1"
                           style={{ color: colors.error }}
                           data-testid="recurring-jobs-price-error">
                    {priceErr}
                  </span>
                ) : null}
              </label>
              <label className="flex items-center gap-2 text-xs font-semibold" style={{ color: colors.muted }}>
                <input type="checkbox" checked={!!editing.allow_sunday}
                       onChange={(e) => setEditing((x) => ({ ...x, allow_sunday: e.target.checked }))}
                       data-testid="recurring-jobs-sunday" />
                Allow Sunday
              </label>
            </div>
            <div className="px-5 py-3 flex items-center justify-end gap-2 shrink-0" style={{ borderTop: `1px solid ${colors.border}` }}>
              <button type="button" onClick={() => { setModalOpen(false); setEditing(null); }}
                      className="text-sm font-semibold px-3 py-1.5 rounded"
                      style={{ border: `1px solid ${colors.border}`, background: colors.surface, color: colors.onSurface }}
                      data-testid="recurring-jobs-cancel">Cancel</button>
              <button type="button" onClick={save} disabled={!editing.customer_id || !editing.service_type || !!priceErr || !propertyGateOk}
                      className="text-sm font-bold px-4 py-1.5 rounded"
                      style={{ background: colors.brand, color: "#fff", border: 0, opacity: (!editing.customer_id || !editing.service_type || !!priceErr) ? 0.5 : 1 }}
                      data-testid="recurring-jobs-save">
                {editing.id ? "Save changes" : "Create"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      {/* Feb-2026 · Recurring Jobs · HARD-delete confirmation modal.
          Distinct from the soft-delete row action so the operator
          has to explicitly opt in to the destructive path. Backend
          removes the template + cancels every future-scheduled
          child job (completed / in-progress children are
          preserved) + writes an audit_logs entry. */}
      {hardDeleteTarget ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center"
              style={{ background: "rgba(15,23,42,0.55)" }}
              data-testid="recurring-job-hard-delete-confirm-modal">
          <div className="w-full max-w-md rounded-2xl"
                style={{ background: colors.surface,
                          border: `1px solid ${colors.border}` }}>
            <div className="flex items-center justify-between px-5 py-3"
                  style={{ borderBottom: `1px solid ${colors.border}` }}>
              <h2 className="text-lg font-bold" style={{ color: "#B91C1C" }}>
                Permanently delete this recurring job?
              </h2>
              <button type="button"
                       onClick={() => setHardDeleteTarget(null)}
                       aria-label="Close">
                <X size={18} />
              </button>
            </div>
            <div className="p-5 text-sm" style={{ color: colors.onSurface }}>
              <p>
                This removes the recurring template AND cancels any
                future scheduled jobs derived from it. Completed jobs
                will not be affected. This cannot be undone.
              </p>
              {(hardDeleteTarget.customer_name || hardDeleteTarget.service_type) ? (
                <p className="mt-3 text-xs" style={{ color: colors.muted }}>
                  Target: <span className="font-semibold" style={{ color: colors.onSurface }}>
                    {hardDeleteTarget.customer_name || "—"} · {hardDeleteTarget.service_type || "—"}
                  </span>
                </p>
              ) : null}
            </div>
            <div className="px-5 py-3 flex items-center justify-end gap-2"
                  style={{ borderTop: `1px solid ${colors.border}` }}>
              <button type="button"
                       onClick={() => setHardDeleteTarget(null)}
                       className="text-sm font-semibold px-3 py-1.5 rounded"
                       style={{ border: `1px solid ${colors.border}`,
                                 background: colors.surface,
                                 color: colors.onSurface }}
                       data-testid="recurring-job-hard-delete-cancel-btn">
                Cancel
              </button>
              <button type="button"
                       onClick={() => hardDelete(hardDeleteTarget)}
                       disabled={busy === hardDeleteTarget.id}
                       className="text-sm font-bold px-4 py-1.5 rounded"
                       style={{ background: "#B91C1C", color: "#FFFFFF",
                                 border: 0,
                                 opacity: busy === hardDeleteTarget.id ? 0.6 : 1 }}
                       data-testid="recurring-job-hard-delete-confirm-btn">
                Delete permanently
              </button>
            </div>
          </div>
        </div>
      ) : null}
      {/* Phase R1 · Feb-2026 — Bulk Hard Delete confirmation modal.
           Independent of the per-row ``hardDeleteTarget`` modal — a
           distinct flow keyed off ``bulkModalOpen``. Primary button
           is gated behind an ack checkbox (no type-to-confirm), and
           displays the running selection count so the operator
           always sees exactly what's about to be permanently
           removed.  Cancel closes without any network activity. */}
      {bulkModalOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center"
              style={{ background: "rgba(15,23,42,0.55)" }}
              data-testid="recurring-bulk-hard-delete-modal">
          <div className="w-full max-w-md rounded-2xl"
                style={{ background: colors.surface,
                          border: `1px solid ${colors.border}` }}>
            <div className="flex items-center justify-between px-5 py-3"
                  style={{ borderBottom: `1px solid ${colors.border}` }}>
              <h2 className="text-lg font-bold" style={{ color: "#B91C1C" }}>
                Permanently delete {selectedIds.size} recurring template{selectedIds.size === 1 ? "" : "s"}?
              </h2>
              <button type="button"
                       onClick={() => { setBulkModalOpen(false); setBulkAcked(false); }}
                       aria-label="Close">
                <X size={18} />
              </button>
            </div>
            <div className="p-5 text-sm" style={{ color: colors.onSurface }}>
              <p className="mb-2">The following will be removed:</p>
              <ul className="list-disc pl-5 space-y-1">
                <li>
                  <span className="font-semibold">{selectedIds.size}</span>{" "}
                  recurring job template{selectedIds.size === 1 ? "" : "s"}
                </li>
                <li>
                  All future scheduled visits (date &ge; today) linked
                  to these templates
                </li>
                <li style={{ color: colors.muted }}>
                  Past / completed visits will be preserved for reporting
                </li>
              </ul>
              <label className="flex items-start gap-2 mt-4 cursor-pointer">
                <input
                  type="checkbox"
                  checked={bulkAcked}
                  onChange={(e) => setBulkAcked(e.target.checked)}
                  className="mt-0.5 cursor-pointer"
                  data-testid="recurring-bulk-hard-delete-ack"
                />
                <span>I understand — this cannot be undone</span>
              </label>
            </div>
            <div className="px-5 py-3 flex items-center justify-end gap-2"
                  style={{ borderTop: `1px solid ${colors.border}` }}>
              <button type="button"
                       onClick={() => { setBulkModalOpen(false); setBulkAcked(false); }}
                       className="text-sm font-semibold px-3 py-1.5 rounded"
                       style={{ border: `1px solid ${colors.border}`,
                                 background: colors.surface,
                                 color: colors.onSurface }}
                       data-testid="recurring-bulk-hard-delete-cancel">
                Cancel
              </button>
              <button type="button"
                       onClick={bulkHardDelete}
                       disabled={!bulkAcked || bulkBusy || selectedIds.size === 0}
                       aria-disabled={!bulkAcked || bulkBusy || selectedIds.size === 0}
                       className="text-sm font-bold px-4 py-1.5 rounded"
                       style={{ background: "#B91C1C", color: "#FFFFFF",
                                 border: 0,
                                 opacity: (!bulkAcked || bulkBusy) ? 0.5 : 1,
                                 cursor: (!bulkAcked || bulkBusy) ? "not-allowed" : "pointer" }}
                       data-testid="recurring-bulk-hard-delete-confirm">
                {bulkBusy ? "Deleting…" : "Permanently Delete"}
              </button>
            </div>
          </div>
        </div>
      ) : null}
      {/* Phase P54 · Feb-2026 — Bulk Edit Categories modal.
           Two dropdowns (Service, Income); each carries an
           "Unchanged" sentinel first-option (empty string) that
           the Apply handler OMITS from the POST payload. Apply is
           disabled when both dropdowns are still "Unchanged", the
           selection is empty, or the request is in-flight. Inline
           error slot picks up backend 422 codes so the operator
           sees the specific failure without a raw toast. */}
      {bulkEditOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center"
              style={{ background: "rgba(15,23,42,0.55)" }}
              data-testid="recurring-bulk-edit-categories-modal">
          <div className="w-full max-w-md rounded-2xl"
                style={{ background: colors.surface,
                          border: `1px solid ${colors.border}` }}>
            <div className="flex items-center justify-between px-5 py-3"
                  style={{ borderBottom: `1px solid ${colors.border}` }}>
              <h2 className="text-lg font-bold"
                  style={{ color: colors.onSurface }}>
                Bulk Edit Categories · {selectedIds.size} template{selectedIds.size === 1 ? "" : "s"}
              </h2>
              <button type="button"
                       onClick={() => { setBulkEditOpen(false); }}
                       aria-label="Close">
                <X size={18} />
              </button>
            </div>
            <div className="p-5 text-sm space-y-3"
                 style={{ color: colors.onSurface }}>
              <p style={{ color: colors.muted }}>
                Pick a new category for every selected recurring
                template. Fields left as <span className="font-semibold">Unchanged</span>
                stay at their current value — only the fields you
                change are written.
              </p>
              <label className="block">
                <span className="block text-xs font-semibold mb-1"
                      style={{ color: colors.muted }}>
                  New Service Category
                </span>
                <select
                  value={bulkEditServiceCat}
                  onChange={(e) => setBulkEditServiceCat(e.target.value)}
                  aria-label="New service category for bulk edit"
                  data-testid="recurring-bulk-edit-service-cat-select"
                  className="w-full text-sm rounded-md py-1.5 px-2"
                  style={{
                    backgroundColor: colors.surface,
                    color: colors.onSurface,
                    border: `1px solid ${colors.border}`,
                  }}
                >
                  <option value="">Unchanged</option>
                  {serviceCats.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </label>
              <label className="block">
                <span className="block text-xs font-semibold mb-1"
                      style={{ color: colors.muted }}>
                  New Income Category
                </span>
                <select
                  value={bulkEditIncomeCat}
                  onChange={(e) => setBulkEditIncomeCat(e.target.value)}
                  aria-label="New income category for bulk edit"
                  data-testid="recurring-bulk-edit-income-cat-select"
                  className="w-full text-sm rounded-md py-1.5 px-2"
                  style={{
                    backgroundColor: colors.surface,
                    color: colors.onSurface,
                    border: `1px solid ${colors.border}`,
                  }}
                >
                  <option value="">Unchanged</option>
                  {incomeCats.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </label>
              {bulkEditError ? (
                <div
                  className="rounded-md px-3 py-2 text-xs"
                  style={{
                    background: "#FEF2F2",
                    border: "1px solid #FECACA",
                    color: "#B91C1C",
                  }}
                  data-testid="recurring-bulk-edit-error"
                >
                  {bulkEditError}
                </div>
              ) : null}
            </div>
            <div className="px-5 py-3 flex items-center justify-end gap-2"
                  style={{ borderTop: `1px solid ${colors.border}` }}>
              <button type="button"
                       onClick={() => { setBulkEditOpen(false); }}
                       className="text-sm font-semibold px-3 py-1.5 rounded"
                       style={{ border: `1px solid ${colors.border}`,
                                 background: colors.surface,
                                 color: colors.onSurface }}
                       data-testid="recurring-bulk-edit-cancel">
                Cancel
              </button>
              <button type="button"
                       onClick={bulkEditApply}
                       disabled={
                         bulkEditBusy ||
                         selectedIds.size === 0 ||
                         (!bulkEditServiceCat && !bulkEditIncomeCat)
                       }
                       aria-disabled={
                         bulkEditBusy ||
                         selectedIds.size === 0 ||
                         (!bulkEditServiceCat && !bulkEditIncomeCat)
                       }
                       className="text-sm font-bold px-4 py-1.5 rounded"
                       style={{
                         background: "#4F46E5", color: "#FFFFFF",
                         border: 0,
                         opacity: (bulkEditBusy ||
                                    (!bulkEditServiceCat && !bulkEditIncomeCat))
                                    ? 0.5 : 1,
                         cursor: (bulkEditBusy ||
                                    (!bulkEditServiceCat && !bulkEditIncomeCat))
                                    ? "not-allowed" : "pointer",
                       }}
                       data-testid="recurring-bulk-edit-apply">
                {bulkEditBusy ? "Applying…" : "Apply"}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────
// Phase P3 · Feb-2026 — Recurring Row 3-dot Actions Menu
// ─────────────────────────────────────────────────────────────────
//
// Inline React component (kept in-file so the top-level page stays
// self-contained — matches the OpsHub team-row kebab pattern which
// is the canonical inline-menu convention already in this codebase).
//
// Props:
//   row             — the recurring-job row this menu acts on. Used
//                     only for the ``active`` flag (Pause vs Resume
//                     label) and the row id (per-item testid suffix).
//   canHardDelete   — gates the "Delete permanently" item. Passed in
//                     from the parent so it stays consistent with
//                     the page-level ``usePermissions`` check.
//   onEdit          — opens the Edit modal for this row.
//   onTogglePause   — flips ``active`` via PATCH /recurring-jobs/{id}.
//   onHardDelete    — opens the row-scoped hard-delete confirmation
//                     modal (the actual DELETE is fired from that
//                     modal's confirm button, not directly here).
//
// Accessibility:
//   • ``aria-label`` on the trigger button and ``aria-haspopup="menu"``.
//   • ``role="menu"`` on the popover.
//   • ``role="menuitem"`` on each action.
//   • Outside-click / Escape dismissers.
//   • Every element with a click handler has a stable testid.
//
// The trigger button and every menuitem call ``stopPropagation`` so
// interacting with the menu never bubbles up to the <tr>'s row-
// click open-modal handler.
function RecurringRowActionsMenu({
  row,
  canHardDelete,
  onEdit,
  onTogglePause,
  onHardDelete,
}) {
  const [open, setOpen] = useState(false);
  const btnRef = useRef(null);
  const menuRef = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => {
      if (menuRef.current?.contains(e.target)) return;
      if (btnRef.current?.contains(e.target)) return;
      setOpen(false);
    };
    const onKey = (e) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const fire = (fn) => (e) => {
    e.stopPropagation();
    setOpen(false);
    fn();
  };

  return (
    <span className="relative inline-block align-middle mr-1"
           onClick={(e) => e.stopPropagation()}
           onMouseDown={(e) => e.stopPropagation()}>
      <button
        ref={btnRef}
        type="button"
        aria-label={`Actions for ${row.customer_name || row.id}`}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={(e) => { e.stopPropagation(); setOpen((v) => !v); }}
        className="inline-flex w-8 h-8 rounded-full items-center justify-center hover:bg-black/5"
        style={{ color: colors.onSurface,
                  border: `1px solid ${colors.border}`,
                  background: colors.surface }}
        data-testid={`recurring-row-actions-btn-${row.id}`}
      >
        <MoreVertical size={16} />
      </button>
      {open ? (
        <div
          ref={menuRef}
          role="menu"
          className="absolute right-0 top-9 z-30 min-w-[220px] rounded-lg shadow-lg py-1 text-left"
          style={{ backgroundColor: "#FFFFFF",
                    border: `1px solid ${colors.border}` }}
          data-testid={`recurring-row-actions-menu-${row.id}`}
        >
          <button
            type="button"
            role="menuitem"
            onClick={fire(onEdit)}
            className="w-full text-left px-3 py-2 text-sm flex items-center gap-2 hover:bg-black/5"
            style={{ color: colors.onSurface }}
            data-testid={`recurring-row-actions-edit-${row.id}`}
          >
            <Pencil size={13} /> Edit
          </button>
          <button
            type="button"
            role="menuitem"
            onClick={fire(onTogglePause)}
            className="w-full text-left px-3 py-2 text-sm flex items-center gap-2 hover:bg-black/5"
            style={{ color: colors.onSurface }}
            data-testid={`recurring-row-actions-pause-resume-${row.id}`}
          >
            {row.active ? <Pause size={13} /> : <Play size={13} />}
            {row.active ? "Pause" : "Resume"}
          </button>
          {canHardDelete ? (
            <button
              type="button"
              role="menuitem"
              onClick={fire(onHardDelete)}
              className="w-full text-left px-3 py-2 text-sm flex items-center gap-2 hover:bg-red-50"
              style={{ color: "#B91C1C" }}
              data-testid={`recurring-row-actions-hard-delete-${row.id}`}
            >
              <Trash2 size={13} /> Delete permanently
            </button>
          ) : null}
        </div>
      ) : null}
    </span>
  );
}
